sys_script_include.script:
var BaseRegistrationValidation = Class.create();
BaseRegistrationValidation.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkBaseCapacity: function() {
        var baseId = this.getParameter('sysparm_base_id');
        if (!baseId) return 'OK';

        var baseGR = new GlideRecord('x_1834930_office_0_office_base');
        if (!baseGR.get(baseId)) return 'OK';

        var maxCapacity = baseGR.getValue('max_capacity');
        if (!maxCapacity) return 'OK';

        var regGR = new GlideRecord('x_1834930_office_0_base_registration');
        regGR.addQuery('base', baseId);
        regGR.addQuery('state', 'IN', '1,2');
        regGR.query();

        var count = 0;
        while (regGR.next()) count++;

        return count >= maxCapacity ? 'FULL' : 'OK';
    },

    checkUserAlreadyRegistered: function() {
        var userId = this.getParameter('sysparm_user_id');
        if (!userId) return 'OK';

        var regGR = new GlideRecord('x_1834930_office_0_base_registration');
        regGR.addQuery('user', userId);
        regGR.addQuery('state', 'IN', '1,2');
        regGR.query();

        return regGR.hasNext() ? 'ALREADY_REGISTERED' : 'OK';
    }

});
